1	package org.springframework.samples.petclinic.util;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone;
11	
12	/**
13	 * Derives an owner's {@code identityKey}: the single value all create-time duplicate detection is
14	 * expressed through. The key is
15	 * {@code normalizedTelephone + "|" + (email or empty) + "|" + (householdId or empty)}, so two
16	 * owners are duplicates only when their <em>whole</em> key is equal. Because the telephone is part
17	 * of the key, two members of the same household (same {@code householdId}) with different telephones
18	 * have different keys and are both allowed; only an exact full-key match is a duplicate.
19	 *
20	 * <p>Each component is normalized the same way for every owner so the comparison is stable:
21	 * the telephone to E.164 (see {@link OwnerTelephone}), the email trimmed and lower-cased, and a
22	 * blank or absent email/householdId represented as the empty string. Normalization is idempotent,
23	 * so the returned key equals the one used for comparison.
24	 */
25	public final class OwnerIdentities {
26	
27	    private OwnerIdentities() {
28	    }
29	
30	    public static String identityKey(Owner owner) {
31	        return normalizeTelephone(owner.getTelephone()) + "|"
32	                + normalizeEmail(owner.getEmail()) + "|"
33	                + normalizeHouseholdId(owner.getHouseholdId());
34	    }
35	
36	    /**
37	     * Builds the owner's {@code customerCode}: {@code '<REGION>-<HASH8>'}. REGION is the canonical
38	     * region derived from the owner's postcode (falling back to city — see {@link Localities}); HASH8
39	     * is the first 8 upper-case hex characters of SHA-256 over
40	     * {@code normalizedTelephone + lastName}. The telephone is normalized to E.164 the same way as in
41	     * {@link #identityKey(Owner)}, so owners differing only in telephone formatting share a code.
42	     */
43	    public static String customerCode(Owner owner) {
44	        String region = Localities.localityFor(owner.getCity(), owner.getPostcode());
45	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
46	        String hash8 = sha256Hex(normalizeTelephone(owner.getTelephone()) + lastName)
47	                .substring(0, 8).toUpperCase(Locale.ROOT);
48	        return region + "-" + hash8;
49	    }
50	
51	    /**
52	     * The owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
53	     * {@code normalizedLastName + "|" + postcode}. Owners with the same last name (normalized to a
54	     * trimmed, whitespace-collapsed, lower-cased form) and the same postcode therefore compute the
55	     * same identifier and belong to the same household automatically — no request has to declare it.
56	     */
57	    public static String householdId(Owner owner) {
58	        String lastName = normalizeName(owner.getLastName());
59	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode().trim();
60	        return sha256Hex(lastName + "|" + postcode).substring(0, 12);
61	    }
62	
63	    /** Full lower-case hex SHA-256 over the UTF-8 bytes of {@code value}. */
64	    private static String sha256Hex(String value) {
65	        try {
66	            byte[] digest = MessageDigest.getInstance("SHA-256")
67	                    .digest(value.getBytes(StandardCharsets.UTF_8));
68	            StringBuilder sb = new StringBuilder(digest.length * 2);
69	            for (byte b : digest) {
70	                sb.append(String.format("%02x", b));
71	            }
72	            return sb.toString();
73	        }
74	        catch (NoSuchAlgorithmException ex) {
75	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
76	        }
77	    }
78	
79	    private static String normalizeName(String value) {
80	        if (value == null) {
81	            return "";
82	        }
83	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
84	    }
85	
86	    private static String normalizeTelephone(String telephone) {
87	        try {
88	            return OwnerTelephone.toE164(telephone);
89	        }
90	        catch (InvalidTelephoneException ex) {
91	            // A value that cannot form a valid E.164 number cannot collide with one that can;
92	            // represent it by its raw form (or empty when absent) so comparison stays total.
93	            return telephone == null ? "" : telephone;
94	        }
95	    }
96	
97	    private static String normalizeEmail(String email) {
98	        if (email == null) {
99	            return "";
100	        }
101	        String trimmed = email.trim();
102	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
103	    }
104	
105	    private static String normalizeHouseholdId(String householdId) {
106	        return (householdId == null || householdId.isBlank()) ? "" : householdId;
107	    }
108	}
