1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	import org.springframework.samples.petclinic.util.OwnerIdentities;
9	
10	/**
11	 * Rejects a create-owner request that exactly duplicates an existing owner's identity. The identity
12	 * is the full {@code identityKey} — {@code telephone + email + householdId} — computed by
13	 * {@link OwnerIdentities#identityKey(Owner)}, so an owner is a duplicate only when its <em>whole</em>
14	 * key matches. Because the telephone is part of the key, two members of the same household (same
15	 * {@code householdId}) with different telephones have different keys and are both allowed; only an
16	 * exact full-key match is rejected with 409 (see {@link DuplicateIdentityException}).
17	 *
18	 * <p>A request may opt in with {@code sharesHousehold=true} to declare that it intentionally joins an
19	 * existing household; doing so <em>bypasses this block</em> entirely.
20	 *
21	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner's {@code householdId}
22	 * is already assigned, and before {@link SaveOwner} so the new owner is not compared against itself.
23	 */
24	public class CheckUniqueIdentity {
25	
26	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return; // declared household member: bypass the duplicate block.
30	        }
31	        String identityKey = OwnerIdentities.identityKey(owner);
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
34	                continue; // never collide with self (should not yet be persisted, but be safe)
35	            }
36	            if (Boolean.TRUE.equals(existing.getDeleted())) {
37	                continue; // a soft-deleted owner no longer blocks a new registration.
38	            }
39	            if (identityKey.equals(OwnerIdentities.identityKey(existing))) {
40	                throw new DuplicateIdentityException(owner.getHouseholdId());
41	            }
42	        }
43	    }
44	}
