1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	
11	/**
12	 * Flags the freshly built {@link Owner} as a soft (non-blocking) duplicate before it is saved.
13	 * A soft duplicate is one that is <em>not</em> a hard duplicate (an exact {@code identityKey}
14	 * match, already rejected with 409 by {@link CheckUniqueIdentity}) but that shares an existing
15	 * owner's {@code lastName} and {@code postcode} while having a <em>different</em> telephone.
16	 *
17	 * <p>When such an existing owner is found the new owner is still created, with
18	 * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
19	 * owner's id (the earliest such owner when several match); otherwise {@code possibleDuplicate} is
20	 * {@code false} and {@code possibleDuplicateOf} is left unset.
21	 *
22	 * <p>Runs after {@link CheckUniqueIdentity} (so hard duplicates are already out) and before
23	 * {@link SaveOwner} (so the new owner is not compared against itself).
24	 *
25	 * <p>An owner that declared {@code sharesHousehold=true} is an intentional household member, not a
26	 * suspected duplicate, so it is never flagged: {@code possibleDuplicate} is left {@code false}.
27	 */
28	public class CheckPossibleDuplicate {
29	
30	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
31	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
32	            owner.setPossibleDuplicate(false);
33	            owner.setPossibleDuplicateOf(null);
34	            return; // a declared household member is not a suspected duplicate.
35	        }
36	        String lastName = normalize(owner.getLastName());
37	        String postcode = normalize(owner.getPostcode());
38	        String telephone = normalizeTelephone(owner.getTelephone());
39	
40	        Integer matchId = null;
41	        if (!lastName.isEmpty() && !postcode.isEmpty()) {
42	            for (Owner existing : ownerRepository.findAll()) {
43	                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
44	                    continue; // never match self
45	                }
46	                if (Boolean.TRUE.equals(existing.getDeleted())) {
47	                    continue; // a soft-deleted owner is not a suspected duplicate match.
48	                }
49	                if (lastName.equals(normalize(existing.getLastName()))
50	                        && postcode.equals(normalize(existing.getPostcode()))
51	                        && !telephone.equals(normalizeTelephone(existing.getTelephone()))) {
52	                    if (matchId == null || existing.getId() < matchId) {
53	                        matchId = existing.getId();
54	                    }
55	                }
56	            }
57	        }
58	
59	        owner.setPossibleDuplicate(matchId != null);
60	        owner.setPossibleDuplicateOf(matchId);
61	    }
62	
63	    private static String normalize(String value) {
64	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
65	    }
66	
67	    private static String normalizeTelephone(String telephone) {
68	        try {
69	            return OwnerTelephone.toE164(telephone);
70	        }
71	        catch (InvalidTelephoneException ex) {
72	            // A value that cannot form a valid E.164 number is represented by its raw form
73	            // (or empty when absent) so the comparison stays total.
74	            return telephone == null ? "" : telephone.trim();
75	        }
76	    }
77	}
