1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.util.OwnerIdentities;
6	
7	/**
8	 * Stamps the deterministic {@code householdId} onto the freshly built {@link Owner}.
9	 *
10	 * <p>The identifier is computed from the owner's own last name and postcode alone (see
11	 * {@link OwnerIdentities#householdId(Owner)}) — the first 12 hex characters of SHA-256 over
12	 * {@code normalizedLastName + "|" + postcode}. It is therefore assigned to <em>every</em> owner,
13	 * not only those that declared {@code sharesHousehold}: owners with the same last name and postcode
14	 * compute the same value and share a household automatically, with no scan of existing owners and no
15	 * back-filling.
16	 *
17	 * <p>Runs after {@link BuildOwner} (which produces the new {@link Owner}) and before the checks that
18	 * key off the household — {@link CheckUniqueIdentity} (the household-duplicate block) and
19	 * {@link CheckPossibleDuplicate} — so the household is fixed before it is consulted.
20	 */
21	public class AssignHousehold {
22	
23	    public void service(@Val Owner owner) {
24	        owner.setHouseholdId(OwnerIdentities.householdId(owner));
25	    }
26	}
