1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
7	
8	/**
9	 * Normalizes a telephone number to E.164 form.
10	 *
11	 * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
12	 * kept as-is; otherwise country code {@code +61} is assumed and a single leading {@code '0'} is
13	 * dropped from the national digits. The result must have 8 to 15 digits after the {@code '+'} or
14	 * the number is rejected as an {@link InvalidTelephoneException}. So {@code "0412 345 678"}
15	 * becomes {@code "+61412345678"} and {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
16	 *
17	 * <p>For recognized country codes the national-number length must match exactly, or the number is
18	 * rejected: {@code +61} (Australia) requires 9 national digits and {@code +1} (NANP) requires 10.
19	 * So {@code "+61 123"} is rejected, while {@code "+61 412 345 678"} and {@code "+1 608 555 1023"}
20	 * are accepted. Numbers whose country code is not recognized keep only the 8-to-15-digit rule.
21	 */
22	public final class OwnerTelephone {
23	
24	    /**
25	     * Recognized country codes mapped to the exact national-number length they require. Ordered
26	     * longest code first so the longest matching prefix wins (e.g. {@code "61"} before {@code "1"}).
27	     */
28	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
29	
30	    static {
31	        NATIONAL_LENGTHS.put("61", 9);
32	        NATIONAL_LENGTHS.put("1", 10);
33	    }
34	
35	    private OwnerTelephone() {
36	    }
37	
38	    public static String toE164(String input) throws InvalidTelephoneException {
39	        if (input == null) {
40	            throw new InvalidTelephoneException(null);
41	        }
42	        String cleaned = input.replaceAll("[\\s()\\[\\]-]", "");
43	        boolean hasPlus = cleaned.startsWith("+");
44	        String rest = hasPlus ? cleaned.substring(1) : cleaned;
45	        if (rest.isEmpty() || !rest.chars().allMatch(c -> c >= '0' && c <= '9')) {
46	            throw new InvalidTelephoneException(input);
47	        }
48	        String digits;
49	        if (hasPlus) {
50	            digits = rest;
51	        }
52	        else {
53	            if (rest.startsWith("0")) {
54	                rest = rest.substring(1);
55	            }
56	            digits = "61" + rest;
57	        }
58	        if (digits.length() < 8 || digits.length() > 15) {
59	            throw new InvalidTelephoneException(input);
60	        }
61	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
62	            String code = country.getKey();
63	            if (digits.startsWith(code)) {
64	                if (digits.length() - code.length() != country.getValue()) {
65	                    throw new InvalidTelephoneException(input);
66	                }
67	                break;
68	            }
69	        }
70	        return "+" + digits;
71	    }
72	}
