1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	
10	/**
11	 * Shared email handling for the owner create/update pipelines. Email is optional; when a
12	 * request carries one it must be a syntactically valid address, and it is stored and
13	 * returned lower-cased.
14	 */
15	final class OwnerEmail {
16	
17	    /**
18	     * A pragmatic address check: a non-empty local part, an {@code @}, then a domain with at
19	     * least one dot and no whitespace. Rejects values like {@code not-an-email} (no {@code @}).
20	     */
21	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
22	
23	    /**
24	     * Disposable email domains that are refused: a present email whose domain is one of these is
25	     * rejected with a 400, so throwaway addresses cannot be registered against an owner.
26	     */
27	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
28	            "mailinator.com", "tempmail.com", "guerrillamail.com");
29	
30	    private OwnerEmail() {
31	    }
32	
33	    /**
34	     * Validates and normalizes the email on the request in place. Absent (null) email is left
35	     * untouched; a present value is trimmed, validated and lower-cased.
36	     *
37	     * @throws InvalidEmailException when an email is present but not a valid address, or when its
38	     *     domain is on the disposable-domain blocklist.
39	     */
40	    static void normalize(OwnerFieldsDto request) throws InvalidEmailException {
41	        String email = request.getEmail();
42	        if (email == null) {
43	            return;
44	        }
45	        String trimmed = email.trim();
46	        if (!EMAIL.matcher(trimmed).matches()) {
47	            throw new InvalidEmailException(email);
48	        }
49	        String normalized = trimmed.toLowerCase(Locale.ROOT);
50	        String domain = normalized.substring(normalized.indexOf('@') + 1);
51	        if (DISPOSABLE_DOMAINS.contains(domain)) {
52	            throw new InvalidEmailException(email);
53	        }
54	        request.setEmail(normalized);
55	    }
56	}
