1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records the {@code namesakeCount} on the freshly built {@link Owner} before it is saved:
9	 * the number of existing owners that share the same first and last name, compared
10	 * case-insensitively.
11	 *
12	 * <p>Runs before {@link SaveOwner} so the new owner is not yet counted — the count reflects
13	 * only owners that existed before this create.
14	 */
15	public class CountNamesakes {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String firstName = normalize(owner.getFirstName());
19	        String lastName = normalize(owner.getLastName());
20	        int count = 0;
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (firstName.equals(normalize(existing.getFirstName()))
23	                    && lastName.equals(normalize(existing.getLastName()))) {
24	                count++;
25	            }
26	        }
27	        owner.setNamesakeCount(count);
28	    }
29	
30	    private static String normalize(String value) {
31	        return value == null ? "" : value.toLowerCase();
32	    }
33	}
