1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown by {@code CheckUniqueIdentity} when a create-owner request would join a household that
5	 * already exists. The household is keyed on {@code (lastName, postcode)} through the deterministic
6	 * {@code householdId}, so a second owner sharing an existing owner's last name and postcode is a
7	 * household duplicate — unless the request declared {@code sharesHousehold=true}, which bypasses the
8	 * block. Handled by {@link DuplicateIdentityExceptionHandler}, which responds 409.
9	 */
10	public class DuplicateIdentityException extends Exception {
11	
12	    public DuplicateIdentityException(String householdId) {
13	        super("An owner already exists in this household: " + householdId);
14	    }
15	}
