14	/**
15	 * Rejects a create-owner request that is missing or blank in any required field, before
16	 * {@link BuildOwner} runs. Each offending field name is collected and reported together as a
17	 * 400 whose {@code errors} array lists them (see {@link MissingOwnerFieldsException}).
18	 *
19	 * <p>Also normalizes the telephone to E.164 form (see {@link OwnerTelephone}): a request whose
20	 * telephone cannot form a valid E.164 number is rejected with a 400 (see
21	 * {@link InvalidTelephoneException}). The normalized E.164 value is stored back on the
22	 * request so it is persisted and returned as {@code telephone}.
23	 *
24	 * <p>Binds the request body for the pipeline and republishes it as a variable so that
25	 * {@link BuildOwner} can read it without a second {@code @RequestBody} binding.
26	 */
27	public class ValidateOwnerFields {
28	
29	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
30	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
31	            InvalidPostcodeException {
32	        // Normalize the supplied address fields first (structured preferred over the flat form) and
33	        // compose the effective 'address', so the required-field check rejects an address that is
34	        // blank only after normalization (e.g. all whitespace), and so the normalized value is
35	        // what every later step persists, returns and compares against. An owner is valid when it
36	        // supplies an address in EITHER form — a non-blank structured 'addressLine1', or the flat
37	        // 'address' — which the composed 'address' being non-blank captures.
38	        OwnerAddress.applyStructured(request);
39	        List<String> missing = new ArrayList<>();
40	        require(missing, "firstName", request.getFirstName());
41	        require(missing, "lastName", request.getLastName());
42	        require(missing, "address", request.getAddress());
43	        require(missing, "city", request.getCity());
44	        require(missing, "telephone", request.getTelephone());
45	        if (!missing.isEmpty()) {
46	            throw new MissingOwnerFieldsException(missing);
47	        }
48	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
49	        OwnerEmail.normalize(request);
50	        OwnerPostcode.validate(request);
51	        validated.set(request);
52	    }
53	
54	    private static void require(List<String> missing, String field, String value) {
55	        if (value == null || value.isBlank()) {
56	            missing.add(field);
57	        }
58	    }
59	}
